#!/usr/bin/env node
/**
 * Generates server/data/sentimony-db-export.json from the catalog source of
 * truth, server/data/sentimony-db.yml.
 *
 * The JSON export is gitignored: it is a build artifact, regenerated by the
 * predev/prebuild/pretest:unit/pregenerate/pretypecheck hooks and by
 * sync:firebase / sync:supabase.
 * Edit the YAML only - hand edits to the JSON are overwritten.
 *
 * Usage:
 *   node scripts/convert-yml-json.mjs
 */

import { parse } from 'yaml'
import { readFileSync, writeFileSync } from 'fs'
import { resolve } from 'path'

const YML_PATH = resolve('server/data/sentimony-db.yml')
const JSON_PATH = resolve('server/data/sentimony-db-export.json')

const source = readFileSync(YML_PATH, 'utf-8')
const data = parse(source)

writeFileSync(JSON_PATH, `${JSON.stringify(data, null, 2)}\n`)

console.log(`Synced ${YML_PATH} -> ${JSON_PATH}`)
